//Standard C libraries
#include <stdbool.h>
#include <stdlib.h>
#include <stdint.h>

//Application C libraries
#define STM32G474xx

#include "stm32g4xx.h"
#include "adc.h"
#include "kobuki.h"
#include "uart.h"
#include "ultrasonic.h"

#include "search_orient.h"
#include "Pathfind.h"
#include "storage.h"
#include "deposit.h"

/* Kobuki button values */
#define BUTTON_0_START  0x01U
#define BUTTON_1_STOP   0x02U
#define BUTTON_2_ROTATE 0x04U

// Logic
#define NULL 0
#define TRUE 1

// States
static enum {
    IDLE,
    SEARCH,
    ORIENT,
    PATHFIND,
    STORAGE,
    DEPOSIT
} state;


typedef enum{
  ORIENT_OPERATIONAL,
  ORIENT_SUCCESS,
  ORIENT_FAIL
}orient_status_t;


typedef struct {
    bool system_start;
    bool system_stop;
    bool wheel_drop;
    bool bumper;
    bool search_done;
    orient_status_t orient_status;
    bool pathfind_complete;
    bool storage_complete;
    bool deposit_complete;
} FSM_Flags_t;


FSM_Flags_t  FSM_flags = {0};

US_Typedef object = {0}; // Zeroed structs to ensure defined behaviour`

// Both of these only for testing purposes. Not required 
volatile uint16_t ultrasonic_read = 0; // Zeroed variables to ensure defined behaviour
volatile uint16_t adc_read = 0; // Zeroed variables to ensure defined behaviour
    

Kobuki_Typedef kobuki = {0}; // Zeroed structs to ensure defined behaviour 
//US_Typedef object = {0}; // Zeroed structs to ensure defined behaviour
Kobuki_LED_Enum led_1, led_2;


int main(void) {


    UART_Init();
    ADC_Init(); // Has to be executed before Ultrasonic Init, because Ultrasonic subroutine uses ADC subroutine
    Ultrasonic_Init();
    
    //Initial assigning of all ENUMS
    state = IDLE;
    led_1 = OFF;
    led_2 = OFF;
    
    while (1) {
        Kobuki_Read(&kobuki);
        Ultrasonic_Detect(&object);
        
        // Both of these only for testing purposes. Not required
        ultrasonic_read = Ultrasonic_Read();
        adc_read = ADC_Read(ADC_CHANNEL_1);
        
        Kobuki_Update_LEDs(led_1, led_2);


        //Global safety case switch
        if((kobuki.button == BUTTON_1_STOP) || (kobuki.wheeldrop > 0)){
            state = IDLE;
        }

        

        // Transition FSM
        switch (state) {
            case IDLE:
            Kobuki_Drive(STOP);

            if (kobuki.button == BUTTON_0_START) {
                Reset_Search();
                state = SEARCH;
            }
            break;
                
            case SEARCH:
                if(Search_FSM(&kobuki,&object)){
                    Start_Orient();
                    state = ORIENT;
                }
            break;
                
            case ORIENT:
            if(Orient_FSM(&kobuki,&object)){
                Start_Pathfind();
                state = PATHFIND;
            }
            break;
                
            case PATHFIND:
            if(Pathfind_FSM(&kobuki)){
                Start_Storage();
                state = STORAGE;
            }
            break;
                
            case STORAGE:
            if(Storage_FSM(&kobuki)){
                Start_Deposit();
                state=DEPOSIT;
            }
            break;
            
            case DEPOSIT:
            if(Deposit_FSM(&kobuki,&object)){
                state=IDLE;
            }
            break;
            
            default:
            break;
        }
    }
}

